package at.andrew.squashtap;
import android.app.Application;import android.net.*;import java.util.*;import java.util.concurrent.*;import org.json.JSONObject;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.util.ReflectionHelpers;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class LiveScoreClientUiTest {
 static final class Queue extends AbstractExecutorService {final java.util.Queue<Runnable> jobs=new ArrayDeque<>();boolean stopped;public void execute(Runnable r){jobs.add(r);}void runAll(){int n=0;while(!jobs.isEmpty()){assertTrue(n++<100);jobs.remove().run();}}public void shutdown(){stopped=true;}public List<Runnable> shutdownNow(){stopped=true;jobs.clear();return Collections.emptyList();}public boolean isShutdown(){return stopped;}public boolean isTerminated(){return stopped;}public boolean awaitTermination(long n,TimeUnit u){return true;}}
 static final class Call {final String method,path,token;final JSONObject body;Call(String m,String p,String t,JSONObject b){method=m;path=p;token=t;body=b;}}
 private Queue q;private List<Call> calls;private LiveScoreClient client;private boolean offline;
 @Before public void setup(){q=new Queue();calls=new ArrayList<>();client=new LiveScoreClient(RuntimeEnvironment.getApplication(),(method,path,token,body)->{calls.add(new Call(method,path,token,body));if(offline&&method.equals("PUT"))throw new java.io.IOException("Offline");return new JSONObject().put("expiresAt",System.currentTimeMillis()+3600000).put("revision",1);},q);}
 @After public void finish(){client.stop(true);q.runAll();q.shutdownNow();}
 private JSONObject score(String id,int point,String phase)throws Exception{return new JSONObject().put("matchId",id).put("points",point).put("phase",phase);}
 @Test public void constructingClientAndScoringBeforeOptInNeverContactsWebsite()throws Exception{client.offer(score("match",3,"playing"));q.runAll();assertTrue(calls.isEmpty());assertNull(client.session());}
 @Test public void audienceLinkCannotWriteAndDoesNotContainOwnerCapability()throws Exception{client.start(score("match",0,"playing"));q.runAll();LiveScoreClient.Session s=client.session();assertTrue(s.ready);assertFalse(s.link().contains(s.owner));assertTrue(s.link().contains(s.viewer));assertTrue(s.link().contains(s.key));assertFalse(calls.get(0).body.has("key"));}
 @Test public void lostConnectionKeepsOnlyLatestPendingScoreAndNeverChangesMatch()throws Exception{client.start(score("match",0,"playing"));q.runAll();LiveScoreClient.Session s=client.session();offline=true;client.offer(score("match",1,"playing"));q.runAll();assertTrue(client.status().startsWith("Offline"));offline=false;client.offer(score("match",2,"playing"));client.offer(score("match",3,"playing"));q.runAll();Call last=calls.get(calls.size()-1);assertEquals("PUT",last.method);assertEquals(3,new JSONObject(TransferCrypto.open(s.id,"out",s.key,last.body.getString("cipher"))).getInt("points"));assertTrue(client.status().startsWith("Live"));}
 @Test public void reconnectRetriesWithoutRequiringAnotherScoredPoint()throws Exception{client.start(score("match",0,"playing"));q.runAll();offline=true;client.offer(score("match",1,"playing"));q.runAll();int before=calls.size();offline=false;ConnectivityManager.NetworkCallback callback=ReflectionHelpers.getField(client,"reconnect");assertNotNull(callback);callback.onAvailable(new Network(17));q.runAll();assertTrue(calls.size()>before);assertTrue(client.status().startsWith("Live"));}
 @Test public void stoppingWhileCreationIsPendingRevokesTheCreatedSession()throws Exception{client.start(score("match",0,"playing"));client.stop(true);q.runAll();assertNull(client.session());assertTrue(calls.stream().anyMatch(c->c.method.equals("DELETE")));assertFalse(calls.stream().anyMatch(c->c.method.equals("PUT")));}
 @Test public void startingAnotherMatchLeavesTheFinishedScoreAvailable()throws Exception{client.start(score("old",0,"playing"));q.runAll();LiveScoreClient.Session s=client.session();client.offer(score("old",11,"finished"));client.offer(score("new",0,"ready"));q.runAll();assertNull(client.session());Call last=calls.get(calls.size()-1);assertEquals("PUT",last.method);assertEquals("finished",new JSONObject(TransferCrypto.open(s.id,"out",s.key,last.body.getString("cipher"))).getString("phase"));}
 @Test public void replacingAnUnfinishedMatchRevokesItsLink()throws Exception{client.start(score("old",2,"playing"));q.runAll();client.offer(score("new",0,"ready"));q.runAll();assertNull(client.session());assertEquals("DELETE",calls.get(calls.size()-1).method);}
 @Test public void staleCreationFailureDoesNotClearANewerSession()throws Exception{final int[] n={0};LiveScoreClient c=new LiveScoreClient(RuntimeEnvironment.getApplication(),(method,path,token,body)->{if(method.equals("POST")&&n[0]++==0)throw new java.io.IOException("late failure");return new JSONObject().put("expiresAt",System.currentTimeMillis()+3600000);},q);c.start(score("old",0,"playing"));c.stop(true);c.start(score("new",0,"playing"));q.runAll();assertNotNull(c.session());assertEquals("new",c.session().matchId);assertTrue(c.session().ready);c.stop(true);q.runAll();}
 @Test public void discardReplacesTheScoreWithAnAnonymousNotice()throws Exception{client.start(score("old",7,"playing"));q.runAll();LiveScoreClient.Session s=client.session();client.discard();q.runAll();assertNull(client.session());Call last=calls.get(calls.size()-1);assertEquals("PUT",last.method);JSONObject d=new JSONObject(TransferCrypto.open(s.id,"out",s.key,last.body.getString("cipher")));assertEquals("discarded",d.getString("phase"));assertEquals(2,d.length());assertEquals("",s.last);assertNull(s.pending);assertNull(ReflectionHelpers.getField(client,"reconnect"));}
 @Test public void offlineDiscardRetriesOnReconnectWithoutAnotherMatchAction()throws Exception{client.start(score("old",7,"playing"));q.runAll();LiveScoreClient.Session s=client.session();offline=true;client.discard();q.runAll();assertTrue(client.status().contains("queued"));ConnectivityManager.NetworkCallback callback=ReflectionHelpers.getField(client,"reconnect");assertNotNull(callback);offline=false;callback.onAvailable(new Network(18));q.runAll();Call last=calls.get(calls.size()-1);assertEquals("discarded",new JSONObject(TransferCrypto.open(s.id,"out",s.key,last.body.getString("cipher"))).getString("phase"));assertNull(ReflectionHelpers.getField(client,"reconnect"));}
 @Test public void discardDuringCreationPublishesItsNoticeWithoutADeletedRoomRace()throws Exception{client.start(score("old",0,"playing"));LiveScoreClient.Session s=client.session();client.discard();q.runAll();assertNull(client.session());assertFalse(calls.stream().anyMatch(c->c.method.equals("DELETE")));Call last=calls.get(calls.size()-1);assertEquals("discarded",new JSONObject(TransferCrypto.open(s.id,"out",s.key,last.body.getString("cipher"))).getString("phase"));}
 @Test public void anOldDiscardNoticeCanFinishWhileANewMatchIsSharing()throws Exception{client.start(score("old",2,"playing"));q.runAll();client.discard();client.start(score("new",0,"playing"));q.runAll();assertNotNull(client.session());assertEquals("new",client.session().matchId);assertTrue(client.status().startsWith("Live"));assertNotNull(ReflectionHelpers.getField(client,"reconnect"));}
 @Test public void aFailedCreationAfterDiscardLeavesNoPendingCallback()throws Exception{LiveScoreClient c=new LiveScoreClient(RuntimeEnvironment.getApplication(),(method,path,token,body)->{throw new java.io.IOException("Offline");},q);c.start(score("old",0,"playing"));c.discard();q.runAll();assertNull(c.session());assertEquals("Match discarded",c.status());assertNull(ReflectionHelpers.getField(c,"reconnect"));assertTrue(((java.util.Map<?,?>)ReflectionHelpers.getField(c,"discarded")).isEmpty());}
 @Test public void completionMetadataIsStableAndUndoStartsANewCompletion()throws Exception{client.start(score("match",0,"playing"));q.runAll();assertEquals(0,calls.get(0).body.getLong("completedAt"));long end=System.currentTimeMillis()-1000;client.offer(score("match",11,"finished").put("finishedAt",end));q.runAll();assertEquals(end,calls.get(calls.size()-1).body.getLong("completedAt"));client.offer(score("match",12,"finished"));q.runAll();assertEquals(end,calls.get(calls.size()-1).body.getLong("completedAt"));client.offer(score("match",10,"playing"));q.runAll();assertEquals(0,calls.get(calls.size()-1).body.getLong("completedAt"));client.offer(score("match",11,"finished").put("finishedAt",end+1));q.runAll();assertEquals(end+1,calls.get(calls.size()-1).body.getLong("completedAt"));}
 @Test public void anOfflineFinalResultRetriesAfterStartingANewMatch()throws Exception{client.start(score("old",0,"playing"));q.runAll();LiveScoreClient.Session old=client.session();offline=true;client.offer(score("old",11,"finished"));client.offer(score("new",0,"ready"));q.runAll();assertNull(client.session());ConnectivityManager.NetworkCallback callback=ReflectionHelpers.getField(client,"reconnect");assertNotNull(callback);offline=false;callback.onAvailable(new Network(21));q.runAll();Call last=calls.get(calls.size()-1);assertEquals("finished",new JSONObject(TransferCrypto.open(old.id,"out",old.key,last.body.getString("cipher"))).getString("phase"));assertTrue(last.body.getLong("completedAt")>0);assertNull(ReflectionHelpers.getField(client,"reconnect"));}
 @Test public void taskRemovalKeepsTheFinishedAudienceResult()throws Exception{client.start(score("match",0,"playing"));q.runAll();client.offer(score("match",11,"finished"));q.runAll();ReflectionHelpers.setStaticField(LiveScoreClient.class,"instance",client);try{LiveScoreClient.stopIfPresent();q.runAll();assertNull(client.session());assertFalse(calls.stream().anyMatch(c->c.method.equals("DELETE")));assertTrue(calls.get(calls.size()-1).body.getLong("completedAt")>0);}finally{ReflectionHelpers.setStaticField(LiveScoreClient.class,"instance",null);}}
}
